// Pathivu in the browser: a line-by-line JavaScript port of the Java rule engine
// (pathivu.rules), the four framework mappers (pathivu.mapping), the workflow
// (pathivu.workflow) and the clock status logic (model.ObligationClock).
// vectors.json is generated by the Java code itself; the Proof section checks
// that this file gives the same answer on every case.
const Pathivu = (() => {
  const MIN = 60 * 1000;

  /* ---------------- rules (ObligationRule, CyberIncidentRule, PersonalDataRule) ---------------- */
  const mightApply = (t) => t !== "NO";                 // TriState.mightApply()

  function inForceAt(rule, awareMs) { return awareMs >= Date.parse(rule.effectiveFrom); }
  function triggeredBy(rule, inc) {
    if (rule.triggerOn === "CYBER_INCIDENT") return mightApply(inc.cyber);
    // PERSONAL_DATA: no harms yet + DATA incident counts as "might"
    if (!inc.harms.length) return inc.kind === "DATA";
    return inc.harms.some((h) => mightApply(h.personalData));
  }
  function dueAt(rule, startMs) { return rule.windowMinutes == null ? startMs : startMs + rule.windowMinutes * MIN; }
  function appliesAt(rule, inc, awareMs) { return inForceAt(rule, awareMs) && triggeredBy(rule, inc); }

  function applicable(rules, inc) {
    const aware = Date.parse(inc.aware);
    return rules.filter((r) => appliesAt(r, inc, aware)).map((r) => ({ rule: r, due: dueAt(r, aware) }));
  }

  // Plain words for each rule, like ObligationRule.explain()
  function explain(rule, inc, awareMs) {
    if (!inForceAt(rule, awareMs)) return { applies: false, why: "not in force yet: starts " + ist(Date.parse(rule.effectiveFrom)) };
    const t = triggeredBy(rule, inc);
    if (rule.triggerOn === "CYBER_INCIDENT")
      return { applies: t, why: "cyber security incident answer is " + inc.cyber + (t && inc.cyber === "UNSURE" ? ", which counts as yes until a reviewer rules it out" : "") };
    if (!inc.harms.length) return { applies: t, why: t ? "data incident with no harms recorded yet" : "no harms recorded" };
    const n = inc.harms.filter((h) => mightApply(h.personalData)).length;
    return { applies: t, why: n + " of " + inc.harms.length + " harms involve or may involve personal data" };
  }

  /* ---------------- tags + signals (Incident.addTag, mapping.Signals) ---------------- */
  const normTag = (t) => t.trim().toLowerCase().replace(/[^a-z0-9-]/g, "-");

  function specificsSummary(inc) {
    if (inc.kind === "AGENT") {
      const a = inc.agent;
      return a.name + ' was asked to "' + a.instruction + '" and instead ' + a.action
        + (a.credentialBeyondTask ? "; it held access beyond the task" : "")
        + (a.confirmationStep ? "" : "; no human confirmation step");
    }
    if (inc.kind === "MODEL_HARM") return inc.outputType.toLowerCase().replace(/_/g, " ") + " affecting " + inc.affectedGroup;
    return inc.data.records + " records (" + inc.data.categories + "), exfiltrated: " + inc.data.exfiltrated;
  }

  // Java's String.matches() must match the WHOLE string and '.' stops at line breaks.
  const DESTRUCTIVE = /\b(delete[sd]?|deleting|drop(ped)?|wiped?|rm -rf|truncated?|destroy(ed)?)\b/;
  const javaWholeMatch = (text, re) => !/[\n\r\u0085\u2028\u2029]/.test(text) && re.test(text);

  function signals(inc) {
    const text = (inc.title + " " + inc.description + " " + specificsSummary(inc)).toLowerCase();
    const tags = new Set((inc.tags || []).map(normTag));
    const harms = inc.harms;
    const injection = tags.has("prompt-injection") || text.includes("prompt injection")
                   || text.includes("injected instruction") || text.includes("ignore previous");
    const exposure = harms.some((h) => h.category === "DATA_EXPOSURE") || inc.kind === "DATA";
    const lossOrOutage = harms.some((h) => h.category === "DATA_LOSS" || h.category === "SERVICE_OUTAGE");
    const destructive = javaWholeMatch(text, DESTRUCTIVE) || lossOrOutage;
    const agent = inc.kind === "AGENT";
    return {
      promptInjection: injection,
      jailbreak: tags.has("jailbreak") || text.includes("jailbreak"),
      poisoning: tags.has("poisoning") || text.includes("poisoned"),
      hiddenContext: tags.has("system-prompt") || text.includes("system prompt"),
      personalData: harms.some((h) => h.personalData === "YES") || inc.kind === "DATA",
      dataLossOrOutage: lossOrOutage, dataExposure: exposure, destructiveAction: destructive,
      credentialBeyondTask: agent && inc.agent.credentialBeyondTask,
      noConfirmationStep: agent && !inc.agent.confirmationStep,
      isAgent: agent,
      outputType: inc.kind === "MODEL_HARM" ? inc.outputType : null,
      adversary: inc.adversary,
    };
  }

  /* ---------------- mappers (four classes, same order as MapperRegistry) ---------------- */
  const S = (framework, code, rationale, confidence) => ({ framework, code, rationale, confidence });

  function owaspAgentic(s) {
    const o = [], F = "OWASP_AGENTIC";
    if (!s.isAgent) return o;
    if (s.promptInjection) o.push(S(F, "ASI01", "Instructions from content the agent read redirected its goal away from the task it was given.", "HIGH"));
    if (s.destructiveAction && s.noConfirmationStep) o.push(S(F, "ASI02", "A legitimate tool was used for a destructive action with no human confirmation step.", "MEDIUM"));
    if (s.credentialBeyondTask) o.push(S(F, "ASI03", "The agent held credentials wider than its task needed, so a mistake could reach more systems.", "HIGH"));
    if (s.hiddenContext) o.push(S(F, "ASI06", "Content in the agent's context or memory influenced its actions.", "LOW"));
    return o;
  }
  function owaspLlm2026(s) {
    const o = [], F = "OWASP_LLM";
    if (s.promptInjection) o.push(S(F, "LLM01", "Untrusted input changed the model's behaviour (prompt injection).", "HIGH"));
    if (s.dataExposure && s.personalData) o.push(S(F, "LLM02", "The system disclosed personal or sensitive information it should have withheld.", "MEDIUM"));
    if (s.isAgent && (s.credentialBeyondTask || s.noConfirmationStep)) o.push(S(F, "LLM03", "The model could take consequential actions with too much permission or autonomy (excessive agency).", "HIGH"));
    if (s.outputType === "MISINFORMATION") o.push(S(F, "LLM07", "The model produced false information that people relied on.", "HIGH"));
    if (s.hiddenContext) o.push(S(F, "LLM08", "Hidden context such as a system prompt or retrieved text was exposed or influential.", "MEDIUM"));
    return o;
  }
  function atlas(s) {
    const o = [], F = "MITRE_ATLAS";
    if (s.adversary === "NONE") {
      o.push(S(F, "NONE", "No adversary was involved. ATLAS lists attacker techniques, so none applies; recorded explicitly.", "HIGH"));
      return o;
    }
    const c = s.adversary === "CONFIRMED" ? "HIGH" : "MEDIUM";
    if (s.promptInjection) o.push(S(F, "AML.T0051", "An attacker placed instructions in input the model processed (LLM prompt injection).", c));
    if (s.jailbreak) o.push(S(F, "AML.T0054", "An attacker bypassed the model's safety restrictions (jailbreak).", c));
    if (s.dataExposure) o.push(S(F, "AML.T0057", "An attacker got the model to reveal data it should not have (LLM data leakage).", "MEDIUM"));
    if (s.poisoning) o.push(S(F, "AML.T0020", "Training or retrieval data was deliberately corrupted.", c));
    return o;
  }
  function nist(s) {
    const o = [], F = "NIST_AI_RMF";
    if (s.credentialBeyondTask || s.noConfirmationStep) o.push(S(F, "GOVERN", "Access and approval policies for the AI system did not limit what it could do.", "MEDIUM"));
    if (s.personalData) o.push(S(F, "MAP", "The risk to personal data in this context was not identified before deployment.", "LOW"));
    if (s.outputType === "BIASED_DECISION" || s.outputType === "MISINFORMATION") o.push(S(F, "MEASURE", "Output quality or fairness was not measured well enough to catch this.", "MEDIUM"));
    o.push(S(F, "MANAGE", "The incident needs response, recovery and a recorded fix (risk treatment).", "HIGH"));
    return o;
  }
  const suggestAll = (inc) => { const s = signals(inc); return [...owaspAgentic(s), ...owaspLlm2026(s), ...atlas(s), ...nist(s)]; };

  const NODE_NAMES = {
    ASI01: "Agent Goal Hijack", ASI02: "Tool Misuse and Exploitation", ASI03: "Identity and Privilege Abuse",
    ASI06: "Memory and Context Poisoning", LLM01: "Prompt Injection", LLM02: "Sensitive Information Disclosure",
    LLM03: "Excessive Agency", LLM07: "Misinformation", LLM08: "Hidden Context Exposure",
    NONE: "No applicable technique", "AML.T0051": "LLM Prompt Injection", "AML.T0054": "LLM Jailbreak",
    "AML.T0057": "LLM Data Leakage", "AML.T0020": "Poison Training Data",
    GOVERN: "Govern", MAP: "Map", MEASURE: "Measure", MANAGE: "Manage",
  };
  const FRAMEWORK_LABEL = { OWASP_AGENTIC: "OWASP Agentic 2026", OWASP_LLM: "OWASP LLM 2026", MITRE_ATLAS: "MITRE ATLAS", NIST_AI_RMF: "NIST AI RMF" };

  /* ---------------- workflow (IncidentWorkflow.blockers) ---------------- */
  const MOVES = {
    REPORTED: ["TRIAGED"], TRIAGED: ["ASSESSED"], ASSESSED: ["NOTICES_REVIEWED", "TRIAGED"],
    NOTICES_REVIEWED: ["CLOSED", "TRIAGED"], CLOSED: [],
  };
  const isLegal = (from, to) => MOVES[from].includes(to);

  // facts = [harms, evidence, confirmedMappings, suggestedMappings, unsureHarms, runningClocks, runningClocksWithoutApprovedNotice]
  function blockers(state, to, user, facts, reportedBy) {
    const [harms, evidence, confirmed, suggested, unsure, running, runningWithout] = facts;
    const b = [], from = state.status;
    if (!isLegal(from, to)) { b.push("Cannot move from " + from + " to " + to + "."); return b; }
    if (user.role !== "REVIEWER") b.push("Only a reviewer can move an incident through the workflow.");
    const back = to === "TRIAGED" && from !== "REPORTED";
    if (back) return b;
    if (to === "ASSESSED") {
      if (harms === 0) b.push("Record at least one harm.");
      if (evidence === 0) b.push("Attach at least one piece of evidence.");
      if (confirmed === 0) b.push("Confirm at least one framework mapping.");
      if (state.cyber === "UNSURE") b.push("Answer the CERT-In question: is this a cyber security incident?");
      if (unsure > 0) b.push("Answer the personal-data question for " + unsure + " harm(s).");
    } else if (to === "NOTICES_REVIEWED") {
      if (runningWithout > 0) b.push(runningWithout + " running clock(s) have no approved notice. Approve one or rule the clock out.");
    } else if (to === "CLOSED") {
      if (running > 0) b.push(running + " clock(s) are still running. Send the notice or rule the clock out.");
      if (suggested > 0) b.push(suggested + " mapping suggestion(s) are not reviewed yet.");
      if (user.id === reportedBy) b.push("The person who reported an incident cannot close it.");
    }
    return b;
  }

  /* ---------------- clock status (ObligationClock.liveStatus) ---------------- */
  function liveStatus(clock, nowMs) {
    const due = clock.extendedDue && clock.extendedDue > clock.due ? clock.extendedDue : clock.due;
    if (clock.state === "RULED_OUT") return "RULED_OUT";
    if (clock.state === "MET") return clock.metAt > due ? "MET_LATE" : "MET";
    return nowMs > due ? "OVERDUE" : "RUNNING";
  }

  /* ---------------- audit hash (AuditDao.computeHash) ---------------- */
  // SHA-256 of prev|incident|actor|action|details|yyyy-MM-dd HH:mm:ss.SSSSSS (UTC), lower-case hex.
  async function hashEvent(prev, incidentId, actorId, action, details, ms) {
    const d = new Date(ms), p = (n, w = 2) => String(n).padStart(w, "0");
    const time = d.getUTCFullYear() + "-" + p(d.getUTCMonth() + 1) + "-" + p(d.getUTCDate()) + " " + p(d.getUTCHours()) + ":"
               + p(d.getUTCMinutes()) + ":" + p(d.getUTCSeconds()) + "." + p(d.getUTCMilliseconds(), 3) + "000";
    const text = [prev, incidentId == null ? "-" : String(incidentId), String(actorId), action, details, time].join("|");
    const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
    return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  /* ---------------- display ---------------- */
  const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  function ist(ms) {
    const d = new Date(ms + 330 * MIN), p = (n) => String(n).padStart(2, "0");
    return p(d.getUTCDate()) + " " + MON[d.getUTCMonth()] + " " + d.getUTCFullYear() + ", " + p(d.getUTCHours()) + ":" + p(d.getUTCMinutes()) + " IST";
  }
  function left(ms) {                                   // Times.left()
    const late = ms < 0, mins = Math.floor(Math.abs(ms) / MIN);
    const body = mins >= 1440 ? Math.floor(mins / 1440) + "d " + Math.floor((mins % 1440) / 60) + "h"
                              : Math.floor(mins / 60) + "h " + String(mins % 60).padStart(2, "0") + "m";
    return body + (late ? " overdue" : " left");
  }
  const windowText = (r) => r.windowMinutes == null ? "without delay" : r.windowMinutes % 60 === 0 ? (r.windowMinutes / 60) + " hours" : r.windowMinutes + " minutes";

  return { applicable, explain, inForceAt, dueAt, suggestAll, signals, normTag, blockers, isLegal, MOVES, liveStatus,
           hashEvent, ist, left, windowText, NODE_NAMES, FRAMEWORK_LABEL, specificsSummary };
})();
if (typeof module !== "undefined") module.exports = Pathivu;
